   using Newtonsoft.Json;

   var attribution = new Dictionary<string, object> {
       ["status"] = "non_organic",
       ["channel"] = "Google Ads",
       ["campaign"] = "Christmas Sale",
       ["ad_group"] = "ad group 1",
       ["ad_set"] = "ad set 1",
       ["creative"] = "creative id 1"
   };

   var attributionJson = JsonConvert.SerializeObject(attribution);
   ```

